    Rules:
    - Four decimal numbers separated by '.'
    - Each number 0-255 inclusive
    - No leading zeros unless the number is exactly "0"
    - Each part consists only of digits
    """
    if not isinstance(s, str):
        return False
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for p in parts:
        if not p:
            return False
        if not p.isdigit():
            return False
        # No leading zeros unless single digit
        if len(p) > 1 and p[0] == '0':
            return False
        # Check numeric range
        try:
            val = int(p)
        except ValueError:
            return False
        if val < 0 or val > 255:
            return False
    return True

