def solve(seq):
    """Run-length encode a sequence.
    Returns a list of [element, count] pairs for each consecutive run.
    Handles any iterable (including strings, bytes, lists). Non‑iterable inputs
    yield an empty list.
    """
    try:
        iterator = iter(seq)
    except TypeError:
        return []
    res = []
    try:
        first = next(iterator)
    except StopIteration:
        return []
    prev = first
    count = 1
    for item in iterator:
        if item == prev:
            count += 1
        else:
            res.append([prev, count])
            prev = item
            count = 1
    res.append([prev, count])
