def solve(n):
    """Return a list of all prime numbers strictly less than integer n.
    Uses the Sieve of Eratosthenes. For n <= 2 returns an empty list.
    """
    # Ensure n is an integer and non-negative
    try:
        n = int(n)
    except Exception:
        return []
    if n <= 2:
        return []
    sieve = [True] * n
    sieve[0:2] = [False, False]  # 0 and 1 are not prime
    import math
    for p in range(2, int(math.isqrt(n - 1)) + 1):
        if sieve[p]:
            step = p
            start = p * p
            sieve[start:n:step] = [False] * ((n - 1 - start) // step + 1)
    return [i for i, is_prime in enumerate(sieve) if is_prime]

