def solve(*args, **kwargs):
    """Flexible RPN evaluator.
    Expects the first positional argument to be the list of tokens.
    """
    if not args:
        return 0
    tokens = args[0]
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:
                stack.append(int(a / b))
        else:
            stack.append(int(token))
    return stack[0] if stack else 0

