def solve(*args):
    # Minimum number of coins to make `amount` from `coins` (unbounded).
    # Bottom-up DP over all amounts: correct even for non-canonical coin
    # systems where greedy fails. Returns -1 when the amount is not
    # reachable; 0 for amount 0.
    if len(args) < 2:
        raise TypeError('solve requires coins and amount')
    coins, amount = args[0], args[1]
    if amount == 0:
        return 0
    if amount < 0:
        return -1
    INF = float('inf')
    dp = [0] + [INF] * amount
    for target in range(1, amount + 1):
        for c in coins:
            if 0 < c <= target and dp[target - c] + 1 < dp[target]:
                dp[target] = dp[target - c] + 1
    return dp[amount] if dp[amount] != INF else -1
